void* PortNegotiationSchema::peekPing(unsigned short x, unsigned short y)
{
	if (x > 8)
		return 0;
	if (y > 8)
		return 0;
	return &m_arr[y + x * 8];
}

int PortNegotiationSchema::GetConnectionState(unsigned short x, unsigned short y)
{
	if (x > 8)
		return 0;
	if (y > 8)
		return 0;
	return m_arr2[y + x * 8];
}

