bool PortNegotiationSchema::rva005DBA9C(bool flag)
{
	if (m_cur >= 8)
		return true;
	if (flag)
	{
		for (int bx = 0; bx < 8; ++bx)
		{
			for (int bp = 0; bp < 8; ++bp)
			{
				if (bx == bp)
					continue;
				GameSlot *gameSlot = m_slots[bx];
				if (!gameSlot)
					continue;
				if (!gameSlot->isHuman())
					continue;
				GameSlot *otherSlot = m_slots[bp];
				if (!otherSlot)
					continue;
				if (!otherSlot->isHuman())
					continue;
				if (m_arr2[bp + bx * 8] != 3)
					return false;
			}
		}
	}
	else
	{
		for (int i = 0; i < 8; ++i)
		{
			if (i == m_cur)
				continue;
			GameSlot *slot = m_slots[i];
			if (!slot)
				continue;
			if (!slot->isHuman())
				continue;
			if (m_arr2[m_cur + i * 8] != 3)
				return false;
			if (m_arr2[i + m_cur * 8] != 3)
				return false;
		}
	}
	return true;
}

